text:
{
  "jobs": [
    {
      "text": "Регулярно созваниваться с матерью, чаще всего по дороге с работы, иногда коротко, иногда долго",
      "quote": "Чаще всего звоню маме, обычно по дороге с работы. Иногда на пять минут, а иногда я уже машину припарковал и ещё полчаса сижу слушаю."
    },
    {
      "text": "Созваниваться с отцом по выходным",
      "quote": "С папой чаще созваниваемся по выходным."
    },
    {
      "text": "Помогать родителям разбираться с подозрительными звонками и проверять, не случилось ли чего",
      "quote": "Я спросил, успела ли она что-нибудь сообщить, и предложил позвонить в банк по номеру на карте."
    },
    {
      "text": "Быть доступным для родителей, даже если это неудобно в моменте",
      "quote": "Я ей сказал, что в таком случае можно звонить хоть посреди совещания."
    },
    {
      "text": "Видеть, дозвонился ли подозрительный звонок до матери, чтобы решить, нужно ли срочно перезванивать",
      "quote": "Я бы хотел сразу видеть, успела мама поговорить или у неё телефон даже не зазвонил. От этого зависит, брошу ли я всё, чтобы ей перезвонить."
    },
    {
      "text": "Получать уведомления только о срабатывании защиты",
      "quote": "Мне хватило бы уве[АДРЕС]о тех случаях, когда сработала защита."
    },
    {
      "text": "Быстро разблокировать нужный номер, если он был ошибочно заблокирован",
      "quote": "А меня после истории с поликлиникой остановило бы, если нужный номер нельзя было бы быстро разблокировать."
    }
  ],
  "pains": [
    {
      "text": "Тревога из-за обычного звонка без пометки, на который родители могут ответить",
      "quote": "Больше всего меня тревожит обычный звонок без всякой пометки."
    },
    {
      "text": "Родители полагаются на определитель номера и не ждут подвоха от звонка без пометки",
      "quote": "Ну телефон же меня не предупредил"
    },
    {
      "text": "Мать боялась отвлекать сына на работе в момент инцидента",
      "quote": "Мама тогда призналась, что боялась отвлечь меня на работе."
    },
    {
      "text": "Непонятно, что увидит сама мама при срабатывании защиты: если разговор оборвётся, она может набрать тот же номер",
      "quote": "Если разговор просто оборвётся, она ведь может решить, что пропала связь, и набрать тот же номер."
    },
    {
      "text": "Заглушение всех незнакомых номеров мешает важным звонкам, например из поликлиники",
      "quote": "Пробовали у мамы заглушить все незнакомые номера, но как раз в ту неделю ей из поликлиники звонили перенести приём. После этого выключили."
    }
  ],
  "current_solutions": [
    {
      "text": "Определитель номера на телефонах родителей; при пометке «спам» трубку не берут",
      "quote": "У обоих родителей стоит определитель номера. Если на экране пометка «спам», они обычно трубку не берут."
    },
    {
      "text": "Пробовали заглушить все незнакомые номера, но отказались из-за пропущенного звонка из поликлиники",
      "quote": "Пробовали у мамы заглушить все незнакомые номера, но как раз в ту неделю ей из поликлиники звонили перенести приём. После этого выключили."
    },
    {
      "text": "Проверка через банк по номеру на карте после подозрительного звонка",
      "quote": "Я спросил, успела ли она что-нибудь сообщить, и предложил позвонить в банк по номеру на карте."
    },
    {
      "text": "Платный определитель номера на своём телефоне примерно за сто рублей в месяц",
      "quote": "За определитель на своём телефоне я плачу около ста рублей в месяц."
    }
  ],
  "barriers": [
    {
      "text": "Барьер выбора: если платить по 150 рублей за каждый номер, сначала хочется попробовать",
      "quote": "Если по 150 за каждый номер, уже захотел бы сначала попробовать."
    },
    {
      "text": "Барьер выбора: важно, чтобы мама сама решала, подключать услугу или нет",
      "quote": "И ей важно самой решать, подключать услугу или нет."
    },
    {
      "text": "Барьер выбора: без быстрой разблокировки нужного номера решение не подошло бы",
      "quote": "А меня после истории с поликлиникой остановило бы, если нужный номер нельзя было бы быстро разблокировать."
    }
  ],
  "triggers": [
    {
      "text": "Маме позвонили «из банка» по поводу кредита на её имя, звонивший знал имя и отчество",
      "quote": "Сказала, что ей только что звонили «из банка» по поводу кредита на её имя. Звонивший знал её имя и отчество, и она сначала поверила."
    },
    {
      "text": "Мама сама позвонила среди рабочего дня и спросила, а вдруг кредит и правда есть",
      "quote": "[имя], а вдруг кредит и правда есть?"
    },
    {
      "text": "Осознание, что после пары месяцев с определителем начинаешь на него полагаться",
      "quote": "Сам бы после пары месяцев с определителем начал на него полагаться."
    }
  ],
  "words": [
    "«из банка»",
    "«Ну телефон же меня не предупредил»",
    "«а вдруг кредит и правда есть?»",
    "«брошу ли я всё, чтобы ей перезвонить»",
    "«сработала защита»",
    "«быстро разблокировать»",
    "«без долгих раздумий»",
    "«взял на пробу и оставил»"
  ],
